import { z } from 'zod';
import { FactAssertionSchema } from './facts';
import { BlockerSchema } from './decisions';
import { CaseViewSchema } from './case';
import { ResultSchema, type Result } from './errors';
import type { CaseSnapshot, CaseView } from './case';
import type { Message } from './messages';
import type { CaseEvent } from './events';
import type { ActionProposal, Draft, PolicyDecision } from './decisions';
import type { AgentProfile, FactSchema } from './configuration';

/** Model output is candidate data, never an authoritative milestone or effect. */
export const InterpretationSchema = z.strictObject({
  assertions: z.array(FactAssertionSchema),
  blockers: z.array(BlockerSchema),
  warnings: z.array(z.string())
});
export type Interpretation = z.infer<typeof InterpretationSchema>;

export interface Interpreter {
  interpret(input: {
    caseSnapshot: CaseSnapshot;
    messages: Message[];
    factSchema: FactSchema;
    agentProfile: AgentProfile;
  }): Promise<Result<Interpretation>>;
}

export interface DraftGenerator {
  generate(input: {
    caseSnapshot: CaseSnapshot;
    proposal: ActionProposal;
    agentProfile: AgentProfile;
    policyDecision: PolicyDecision;
  }): Promise<Result<Draft>>;
}

export interface EventReceipt {
  eventId: string;
  caseId: string;
  revision: number;
}

export interface EventAppendResult { receipt: EventReceipt; duplicate: boolean }

export interface CaseRepository {
  get(caseId: string): Promise<Result<CaseSnapshot>>;
  saveIfRevision(snapshot: CaseSnapshot, expectedRevision: number): Promise<Result<CaseSnapshot>>;
  appendEvent(event: CaseEvent): Promise<Result<EventAppendResult>>;
  appendEventWithSnapshot(event: CaseEvent, snapshot: CaseSnapshot): Promise<Result<EventAppendResult>>;
  reset(caseId: string): Promise<Result<CaseSnapshot>>;
}
export type ApplicationResult = Result<CaseView>;

export const ApplicationResultSchema = ResultSchema(CaseViewSchema);
import { z } from 'zod';
import { ConfigBundleRefSchema, Id, Revision } from './primitives';
import { MessageSchema } from './messages';
import { CaseKnowledgeSchema, FactAssertionSchema } from './facts';
import { CaseEventSchema } from './events';
import { ApplicationErrorSchema } from './errors';
import { ActionProposalSchema, BlockerSchema, DecisionRecordSchema, DraftSchema, GoalSchema, WorkflowProgressSchema } from './decisions';

export const CaseSnapshotSchema = z.strictObject({
  caseId: Id,
  revision: Revision,
  messages: z.array(MessageSchema),
  assertions: z.array(FactAssertionSchema),
  knowledge: CaseKnowledgeSchema,
  goal: GoalSchema,
  workflowProgress: WorkflowProgressSchema,
  blockers: z.array(BlockerSchema),
